custom_css:
/* 作者：蘑菇蟑螂汤（dc） */
/* 素材来自小红书-牛逼哄哄咩小耶 */
/* 感谢deepseek和Gemini */

@import url("https://fontsapi.zeoseven.com/285/main/result.css");
@import url("https://fontsapi.zeoseven.com/292/main/result.css");


body, input, textarea, code, select {
   font-family:  var(--mainfont), "Microsoft YaHei", sans-serif !important;
    font-weight: normal;
}
:root{
    --mainfont: 'Noto Serif CJK';
    --monoFontFamily: 'Noto Serif CJK';
    --black30a: #eee;
    --white30a: #888;
    --golden: #888;
    --grey7070a: rgb(255 255 255);
    --white50a: #62708294;
    --black50a: transparent;
}
/* 隐藏滑动条 */
*{
  scrollbar-width: none; /* Firefox */
  -ms-overflow-style: none; /* IE/Edge */
}

/* WebKit浏览器 (Chrome/Safari) */
*::-webkit-scrollbar {
  display: none;
  width: 0;
  height: 0;
}
#chat {
    padding: 0px 5px;
    display: flex
;
    align-items: center !important;
    backdrop-filter: none;
}
#chat .mes {
    display: flex
;
    flex-direction: column;
    margin: 50px 0px 20px !important;
    position: relative;
}
#chat .mesAvatarWrapper {
    display: flex
;
    flex-direction: row;
    height: 50px;
    align-items: flex-end;
}
.last_mes .mesAvatarWrapper {
    padding-bottom: 0px;
}
.mes_block .ch_name {
    max-width: 80%;
    min-height: 22px;
    align-items: stretch;
    display: flex
;
    flex-direction: row;
    z-index: 2;
}
.mes .mes_timer, .mes .mesIDDisplay, .mes .tokenCounterDisplay {
    font-weight: normal;
    margin-top: 0px;
    margin-right: 15px;
    border-radius: 5px;
    padding: 0px 8px;
    background: #ffffff5e;
    backdrop-filter: blur(10px) !important
}
.mes_block {
    margin-top: -50px;
    padding: 0px;
}
.mes_text {
    margin: 30px 0px 0px;
    padding: 10px;
    background: #ffffff5e;
    backdrop-filter: blur(10px) !important;
    text-align: justify;
}
#chat .avatar img {
    width: var(--avatar-base-width);
    height: var(--avatar-base-height);
    border: 2px solid rgb(255 255 255);
    box-shadow: 0 0 5px rgb(255 255 255);
}
.mes .avatar {
    position: absolute;
    left: 20px;
}
#chat .mes_block .ch_name{
    margin: 5px 0px 0px 60px;
}
.mes[is_user="true"] .mes_timer{
    margin-right: 0px;
} 
.mesIDDisplay {
    margin-left: 70px;
}

.mes_reasoning {
    margin: 40px 0px 0px 0px;
    text-align: justify;
    background: #ffffff5e;
    backdrop-filter: blur(10px);
}
#chat .alignItemsBaseline {
    align-items: center;
    padding: 3px 10px;
    background: #ffffff5e;
    backdrop-filter: blur(10px);
    border-radius: 10px;
    flex-direction: row;
}
.drawer-content .alignItemsBaseline, .flex-container.alignitemscenter[title="Default display style for media attachments in chat messages. Extensions can override this setting."] {
    background: #ffffff5e;
    backdrop-filter: blur(10px);
    padding: 5px 5px 5px 10px;
    border-radius: 20px !important;
}

/* 顶部 */
#top-bar{
   box-shadow: none !important;
}
#top-settings-holder .drawer-toggle{
    padding: 0 !important; /* 移除内边距 */
    width: fit-content !important; /* 自适应图标宽度 */
}
#top-settings-holder .drawer-icon{
    padding: 4px; /* 图标周围保留4px点击区域 */
    font-size: 20px !important; /* 可选：缩小图标尺寸 */
    color:transparent;
}
#sys-settings-button .drawer-toggle,
#WI-SP-button .drawer-toggle,
#backgrounds-button .drawer-toggle,
#logo-block .drawer-toggle,
#table_database_settings_drawer .drawer-toggle,
#rightNavHolder .drawer-toggle,
#advanced-formatting-button .drawer-toggle,
#user-settings-button .drawer-toggle ,
#ai-config-button .drawer-toggle,
#extensions-settings-button .drawer-toggle,
#persona-management-button .drawer-toggle
{
background-image: url(https://i.postimg.cc/Xq8kJ80v/1.png) !important;
    background-repeat: no-repeat;
    background-position: center;
    background-size: contain;
    width: 25px;
    height: 25px;
    display: inline-block;
    color: transparent;
}
#extensionTopBar {
    border-radius: 0px !important;
}
/* 编辑按钮 */
/* 编辑按钮 */
.mes_button, .extraMesButtons>div {
    filter: none;
}
#chat .mes .ch_name .fa-pencil:before, .fa-ellipsis-h:before {
    background-image: url(https://i.postimg.cc/NFmRVv4S/3.png);
    background-repeat: no-repeat;
    color: transparent;
    font-size: 20px;
    background-size: contain;
}
 .fa-ellipsis:before{
    background-image: url(https://i.postimg.cc/05ZSh56m/4.png);
    background-repeat: no-repeat;
    color: transparent;
    font-size: 20px;
    background-size: contain;
}
#send_form {
    height: auto !important;
    min-height: 55px !important;
    border-radius:20px;
    width: -webkit-fill-available;
    border-color: transparent !important;
    margin: 0px 20px;
    flex-direction: row !important;
    justify-content: center !important;
    align-items: center;
    padding:10px;
}
.fa-bars::before,
.fa-magic-wand-sparkles::before{
    display: none !important; /* 隐藏 Font Awesome 图标 */
}

#send_but::before{
    display: none !important; /* 隐藏 Font Awesome 图标 */
}

#options_button {
    background-image: url(https://i.postimg.cc/JhSwrHpF/5.png) !important;
    background-size: contain;
    background-repeat: no-repeat;
    background-position: center;
    width: 25px !important;
    height: 25px !important;
}
#extensionsMenuButton {
    background-image: url(https://i.postimg.cc/8zVqsrgJ/6.png) !important;
    background-size: contain;
    background-repeat: no-repeat;
    background-position: center;
    width: 25px !important;
    height: 25px !important;
    margin-left: 10px !important;
}
/* 替换 "发送消息" (纸飞机按钮) */
#send_but {
    background-image: url(https://i.postimg.cc/1RgjrWxZ/7.png) !important;
    background-size: contain;
    background-repeat: no-repeat;
    background-position: center;
    width: 25px !important;
    height: 25px !important;
}
.fa-solid.fa-circle-stop {
    /* 隐藏Font Awesome的字体图标 */
    font-size: 0 !important;
    color: transparent !important;

    /* 用自定义图片替换 */
    display: inline-block;
    width: 25px !important;
    height: 25px !important;
    background-image: url('https://i.postimg.cc/mkpCJ93d/8.png');
    background-repeat: no-repeat;
    background-size: contain;

    /* 新增的呼吸悬浮动画 */
    animation: float-and-breathe 3s ease-in-out infinite;
}

/* 定义呼吸悬浮动画的关键帧 */
@keyframes float-and-breathe {
    0%, 100% {
        transform: translateY(0) scale(1);
    }
    50% {
        transform: translateY(-5px) scale(1.1);
    }
}
/* 底栏QR按键隐藏 */
#send_form:hover #qr--bar {
    height: 35px;
    transition: all 0.5s ease;
}
#qr--bar {
    height: 0.5px;
}

#quick-reply-rocket-button {
    font-size: 0.8em !important;
    margin-right: 10px !important;
}


.reasoning_edit_textarea, .edit_textarea {
    background-color: rgb(255 255 255 / 50%);
    border: 1px dashed grey;
}
.mes_edit_buttons {
    filter: none;
}
.mes_edit_buttons .menu_button, .mes_reasoning_actions .edit_button {
    background: #ffffff;
    margin-top: 20px;
    margin-bottom: -20px;
}
.reasoning_edit_textarea {
    margin-top: 40px;
}
/* 导入框 */
#extensions_settings .inline-drawer-toggle.inline-drawer-header, #extensions_settings2 .inline-drawer-toggle.inline-drawer-header, #user-settings-block h4, .standoutHeader, .userSettingsInnerExpandable,
#tagInput, #completion_prompt_manager #completion_prompt_manager_list li.completion_prompt_manager_prompt {
    background: #fff;
    box-shadow: 0px 2px 2px #c4c4c4;
    padding: 6px 12px !important;
    border-radius: 10px !important;
}
select {
    background: #eeeeee !important;
    padding: 6px 6px 6px 12px !important;
    border-radius: 15px !important;
}
.fa-chevron-circle-up:before, .fa-circle-chevron-up:before, .fa-chevron-circle-down:before, .fa-circle-chevron-down:before {
    content: "\f1ce";
    font-size: 0.8em;
}
/* 滑块 */
/* 清除所有浏览器默认外框 */
input[type="range"]::-webkit-slider-thumb {
    -webkit-appearance: none;
    appearance: none;
    margin: 0;
    padding: 0;
    width: 100%;
    height: 2px;
    border-radius: 0px;
    background-size: 70% 100%;
    background-repeat: no-repeat;
    box-shadow: none;
    cursor: ew-resize;
}
input[type="range"] {
    -webkit-appearance: none !important;
    border-radius: 0px !important;
    height: 1.5px !important;
    background: grey !important;
    box-shadow: none !important;
}
input[type="number"] {
    background-color: #ffffff5e;
    backdrop-filter: blur(10px);
    border-radius: 0px;
    margin-top: 10px;
}

input[disabled], textarea[disabled] {
    background: grey !important;
    -webkit-text-fill-color: grey !important;
}
/* 滑块按钮样式 */
input[type="range"]::-webkit-slider-thumb {
  width:10px;
  height: 10px;
  background: grey;
  cursor: pointer;
  border-radius: 50%;
}
.mes.smallSysMes .mesAvatarWrapper {
    display: none !important;
    height: unset !important;
    min-height: unset;
}

/* 复选框 */
/* check框 */
input[type="checkbox"] {
    background: #fff;
    border: none;
    box-shadow: none;
  border-radius: 50%;
}
input[type="checkbox"]:checked {
    background: url(https://i.postimg.cc/FsCVRSss/10.png);
    background-size: contain;
    background-repeat: no-repeat;
    box-shadow: none;
    border: none !important;
    width: 1.5em;
    height: 1.5em;
    outline: none;
}
input[type="checkbox"]::before {
    box-shadow: none;
}
/* 文字框 */
textarea {
    background: #ffffff88;
}
.text_pole {
    background-color: rgb(255 255 255);
    color: rgb(0 0 0);
    border-radius: 5px;
    padding: 6px;

}
/* 正则 */
.regex-script-container {
    margin-right: 45px;
}
.drag-handle {
    color: rgb(0 0 0);
}
.regex-script-label {
    border-left: 1.5px solid grey !important;
    background: #4a4a4a14 !important;
    border-radius: 0px !important;
    padding: 0px 5px;
}
#completion_prompt_manager .completion_prompt_manager_header {
    color: rgb(0 0 0 / 53%);
}
#completion_prompt_manager .completion_prompt_manager_header_advanced span {
    filter: none;
}
/* 预设 */
#completion_prompt_manager #completion_prompt_manager_list li.completion_prompt_manager_prompt .prompt_manager_prompt_controls span {
    filter: none;
}
#completion_prompt_manager #completion_prompt_manager_list {
    background: transparent;
}
#completion_prompt_manager #completion_prompt_manager_list .completion_prompt_manager_prompt.completion_prompt_manager_prompt_disabled {
    background: transparent;
    box-shadow: none;
    border: none;
}
/* 角色选择 */
.character_select.entity_block.flex-container.interactable.is_fav,
#user_avatar_block .bogus_folder_select, #user_avatar_block .character_select, #user_avatar_block .avatar-container.selected {
    outline-offset: -5px;
    background: #ffffff;
    box-shadow: 0px 2px 4px 2px #00000022;
    margin: 5px 0px;
    padding: 10px;
    position: relative;
}
.hotswap.avatars_inline.scroll-reset-container {
 flex-wrap: nowrap;
 overflow-y: auto;
 overflow-x: hidden;
 -webkit-overflow-scrolling: touch;
 min-height: 50px;

 /* 添加左右外边距 */
 margin-inline-start: 50px; /* 根据需要调整数值 */
 margin-inline-end: 50px;   /* 与左外边距保持一致 */
}

.character_select.is_fav .avatar, .group_select.is_fav .avatar, .group_member.is_fav .avatar, .avatar.is_fav {
    outline: 2px solid transparent;
}
.character_select.is_fav .ch_name, .group_select.is_fav .ch_name, .group_member.is_fav .ch_name {
    color: #000;
}
.fav_on, .world_set, .toggleEnabled {
    color: #c6c6c6 !important;
}
/* 标签 */
.tag {
    filter: none;
    border: none;
    background: #fff;
}
.tag.actionable {
    background: #fff !important;
    border: none;
}
/* 双引号引用 */
.mes_text q {
    color: var(--SmartThemeQuoteColor);
    font-family: "LXGW WenKai";
    font-weight: normal;
    font-style: normal;
}
mes_text i:not([class*="icon"]):not(i[class^="fa-"]), .mes_text em:not([class*="icon"]):not([class^="fa-"]) {
font-style: normal;
background: #ffffff91;
padding: 1px 4px;
border-left: 1.5px solid #a5a5a5;
display: inline-block;
}
code {
color: #626262;
border-bottom: 1px dashed;
background: transparent;
border-radius: 0px;
}
.hljs{
border-bottom: none !important;
}
.world_entry {
    transition: opacity 500ms;
    background: #ffffffaa;
    margin: 15px 10px;
    border-radius: 10px;
    box-shadow: 3px 2px 3px #c1c1c1;
}
.mes_text blockquote, .mes_reasoning blockquote {
    border-left: 1.5px solid var(--SmartThemeQuoteColor);
    padding-left: 10px;
    background-color: var(--black30a);
    margin: 0;
}
.hotswap.avatars_inline.scroll-reset-container {
    flex-wrap: wrap;
    overflow-y: auto;
    overflow-x: hidden;
    -webkit-overflow-scrolling: touch;
    min-height: 50px;
    margin-inline-start: 10px;
    margin-inline-end: 10px;
}

/* 修复 */
.mes_block .ch_name {
    flex-direction: column;
    margin-bottom: -20px !important;
}
.mes_reasoning_details .mes_reasoning_summary {
    margin-bottom: -25px;
    margin-top: 15px;
}
.mes_reasoning_header_block::after {
    pointer-events: none;
    top: 0px;
}
.mes_text pre code, .mes_reasoning pre code {
    border-radius: 20px;
    background: #fff;
    box-shadow: 2px 2px 3px #eee;
    color: #7b7b7b;
    border: none;
}
.mes_reasoning {
    max-height: 400px;
    overflow-y: auto;
    overflow-x: hidden;
    margin-left: 25px;
    padding: 10px !important;
    border: 1.5px solid;
}
.mes_reasoning_header.flex-container {
    background: transparent;
    color: transparent;
    position: relative;
    width: 100%;
}
.mes_reasoning_header.flex-container::before {
    content: "°.✩┈…୨୧…┈✩.° 𝐓𝐰𝐢𝐧-𝐖𝐢𝐧𝐠 𝐈𝐧𝐬𝐞𝐜𝐭 °.✩┈…୨୧…┈✩.°";
    font-size: 13px;
    position: absolute;
    top: 0px;
    padding: 9px;
    width: 95%;
    left: 50%;
    transform: translateX(-50%);
    text-align: center;
    pointer-events: none;
  color: var(--SmartThemeBodyColor);
}
